def _pin(data):return len(data),hashlib.sha256(data).hexdigest()

def transform_source(source):
    if type(source)is not bytes or _pin(source)!=INPUT:raise ValueError('fixed full F post-pool input')
    result=source
    for a,b,old,new in reversed(EDITS):
        if source[a:a+len(old)]!=old:raise ValueError('fixed binding role')
        result=result[:a]+new+result[a+len(old):]
    if _pin(result)!=OUTPUT:raise ValueError('fixed binding output')
    inverse=result
    for a,b,old,new in reversed(EDITS):
        if result[b:b+len(new)]!=new:raise ValueError('fixed inverse binding role')
        inverse=inverse[:b]+old+inverse[b+len(new):]
    if inverse!=source:raise ValueError('complete binding inverse')
    for a,b,size,digest in GAPS:
        if source[a:a+size]!=result[b:b+size]or _pin(source[a:a+size])!=(size,digest):raise ValueError('protected binding gap')
    return result,dict(METADATA)

def restore_source(source):
    if type(source)is not bytes or _pin(source)!=OUTPUT:raise ValueError('fixed frequency output')
